def solve2(g):
    H,W=len(g),len(g[0])
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]==2:
                nb=sum(1 for di,dj in ((1,0),(-1,0),(0,1),(0,-1))
                       if 0<=i+di<H and 0<=j+dj<W and g[i+di][j+dj]==3)
                if nb>=2:
                    for di in (-1,0,1):
                        for dj in (-1,0,1):
                            ni,nj=i+di,j+dj
                            if 0<=ni<H and 0<=nj<W and out[ni][nj]!=2:
                                out[ni][nj]=1
    return out
